import { renderComponent } from '@ember/renderer';
import { Greeting } from './greeting.gjs';

class EmberGreetingElement extends HTMLElement {
  constructor() {
    super();
    this._renderResult = null;
  }

  static get observedAttributes() {
    return ['name'];
  }

  connectedCallback() {
    this._render();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (!this.isConnected) return;
    this._render();
  }

  disconnectedCallback() {
    if (this._renderResult) {
      this._renderResult.destroy();
      this._renderResult = null;
    }
  }

  _render() {
	    if (this._renderResult) {
	      this._renderResult.destroy();
	      this._renderResult = null;
	    }

	    this._renderResult = renderComponent(Greeting, {
      into: this,
      args: {
			name: this.getAttribute('name') ?? 'world',
      },
    });
  }
}

customElements.define('ember-greeting', EmberGreetingElement);

