import { renderComponent } from '@ember/renderer';

export function defineEmberCustomElement(tagName, Component, options = {}) {
	const { attributes = [], callbackProps = [] } = options;

	class EmberCustomElement extends HTMLElement {
		constructor() {
			super();
			this._renderResult = null;
			this._callbacks = Object.create(null);
		}

		static get observedAttributes() {
			return attributes;
		}

		connectedCallback() {
			this._render();
		}

		attributeChangedCallback(name, oldValue, newValue) {
			if (oldValue === newValue) return;
			if (!this.isConnected) return;
			this._render();
		}

		disconnectedCallback() {
			if (this._renderResult) {
				this._renderResult.destroy();
				this._renderResult = null;
			}
		}

		_buildArgs() {
			let args = {};

			// Atributos HTML -> args do componente
			for (let attr of attributes) {
				let value = this.getAttribute(attr);
				if (value === null) continue;

				if (value === 'true') {
					value = true;
				} else if (value === 'false') {
					value = false;
				}

				args[attr] = value;
			}

			// Propriedades de callback (funções) expostas no custom element
			for (let prop of callbackProps) {
				let fn = this._callbacks && this._callbacks[prop];
				if (typeof fn === 'function') {
					args[prop] = fn;
				}
			}

			return args;
		}

		_render() {
			if (this._renderResult) {
				this._renderResult.destroy();
				this._renderResult = null;
			}
			this._renderResult = renderComponent(Component, {
				into: this,
				args: this._buildArgs(),
			});
		}
	}

	// Define dinamicamente propriedades de callback no prototype do custom element,
	// de forma que atribuir `element.onClick = fn` (por exemplo) reprocesse os args.
	for (let prop of callbackProps) {
		if (prop in EmberCustomElement.prototype) continue;

		Object.defineProperty(EmberCustomElement.prototype, prop, {
			get() {
				return this._callbacks && this._callbacks[prop];
			},
			set(value) {
				if (!this._callbacks) {
					this._callbacks = Object.create(null);
				}
				this._callbacks[prop] = value;

				if (this.isConnected) {
					this._render();
				}
			},
		});
	}

	if (!customElements.get(tagName)) {
		customElements.define(tagName, EmberCustomElement);
	}
}

